151	/* ─── Lista compacta item (painel esquerdo) — visual VisaoFinanceira ─── */
152	function AssetListItem({
153	    investment,
154	    isSelected,
155	    onClick,
156	    index,
157	}: {
158	    investment: PosAquisicaoWithCedentes;
159	    isSelected: boolean;
160	    onClick: () => void;
161	    index: number;
162	}) {
163	    const scenarioKey = mapScenarioFromAPI(investment.selected_scenario) || 'base';
164	    const scenario = investment.profitability_scenarios?.[scenarioKey];
165	    const tir = parseNullableDecimal(scenario?.tir);
166	    const moic = parseNullableDecimal(scenario?.moic);
167	    const valorLiquido = parseFloat(investment.valor_liquido_disponivel || '0');
168	    const cessionario = investment.cessionarios?.[0]?.nome || '-';
169	    const cessaoRegistrada = !!investment.cessao_registrada;
170	
171	    return (
172	        <button
173	            onClick={onClick}
174	            className={cn(
175	                'relative flex flex-col gap-1.5 rounded-2xl border px-3.5 py-3 text-left transition-all duration-200',
176	                isSelected
177	                    ? 'border-[#96FF00]/30 bg-[#f3f6f9] shadow-[0_4px_16px_-4px_rgba(0,0,0,0.10),0_0_0_1px_rgba(150,255,0,0.10)] dark:border-[#96FF00]/10 dark:bg-[#131a21] dark:shadow-[0_8px_24px_-8px_rgba(0,0,0,0.6),0_0_0_1px_rgba(150,255,0,0.05)]'
178	                    : 'border-transparent hover:bg-black/3 dark:hover:bg-white/4',
179	            )}
180	        >
181	            {index > 0 && !isSelected && (
182	                <div className="absolute -top-px left-3.5 right-3.5 h-px bg-black/6 dark:bg-white/[0.07]" />
183	            )}
184	
185	            <div className="flex items-center justify-between gap-2">
186	                <p
187	                    className={cn(
188	                        'truncate text-sm font-bold tracking-tight',
189	                        isSelected
190	                            ? 'text-[#0b1014] dark:text-white'
191	                            : 'text-[#536471] dark:text-[#8a9097]',
192	                    )}
193	                >
194	                    {investment.credor}
195	                </p>
196	                <div className="flex shrink-0 items-center gap-1">
197	                    <ImportadoBadge
198	                        importado={!!investment.importado}
199	                        variant="icon"
200	                    />
201	                    <span
202	                        className={cn(
203	                            badgeVariants({ variant: investment.revisado ? 'green' : 'red' }),
204	                            'shrink-0 border-none px-1.5 py-px text-[8px] font-bold uppercase tracking-wide',
205	                        )}
206	                    >
207	                        {investment.revisado ? 'Revisado' : 'Não revisado'}
208	                    </span>
209	                </div>
210	            </div>
211	
212	            <div
213	                className={cn(
214	                    'flex items-center gap-1.5 text-[11px] font-medium',
215	                    isSelected
216	                        ? 'text-[#536471] dark:text-[#6f7a83]'
217	                        : 'text-[#5d6770] dark:text-[#8a9097]',
218	                )}
219	            >
220	                <span
221	                    className={cn(
222	                        'h-[5px] w-[5px] shrink-0 rounded-full',
223	                        cessaoRegistrada ? 'bg-[#96FF00]' : 'bg-[#f97316]',
224	                    )}
225	                />
226	                <span className="truncate">
227	                    {cessionario} · {investment.ente_devedor}
228	                </span>
229	            </div>
230	
231	            <div className="flex items-center gap-3 text-[11px] tabular-nums">
232	                {/* Qualifica justamente a TIR e o MOIC ao lado, que podem ser do
233	                    snapshot anterior quando o recálculo falhou. */}
234	                <MarcadorCenarioCalc recurso={investment} />
235	                {(
236	                    [
237	                        [
238	                            'TIR',
239	                            tir !== null ? `${(tir * 100).toFixed(1)}%` : '—',
240	                            isSelected
241	                                ? 'text-[#4d8f00] dark:text-[#96FF00]'
242	                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
243	                        ],
244	                        [
245	                            'MOIC',
246	                            moic !== null ? `${moic.toFixed(2)}x` : '—',
247	                            isSelected
248	                                ? 'text-[#536471] dark:text-white'
249	                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
250	                        ],
251	                        [
252	                            'Vlr.',
253	                            `R$ ${(valorLiquido / 1000).toFixed(1)}k`,
254	                            isSelected
255	                                ? 'text-[#536471] dark:text-white'
256	                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
257	                        ],
258	                    ] as const
259	                ).map(([label, value, color]) => (
260	                    <span key={label}>
261	                        <span className="text-[#8a9097] dark:text-[#3d4850]">{label} </span>
262	                        <span className={cn('font-semibold', color)}>{value}</span>
263	                    </span>
264	                ))}
265	            </div>
266	        </button>
267	    );
268	}
