281	/* ─── Main wrapper ─── */
282	export function IndividualCardsWrapper({
283	    urlFilters,
284	    setUrlFilters,
285	    onDataChange,
286	    onEditItem,
287	    onNewItem,
288	}: IndividualCardsWrapperProps) {
289	    const [individualViewMode, setIndividualViewMode] = useQueryState(
290	        'individual_view_mode',
291	        parseAsString.withDefault(getStorageItem('individual_view_mode') ?? 'rows'),
292	    );
293	    const [selectedId, setSelectedId] = useQueryState(FINANCIAL_ATIVO_PARAM, parseAsString);
294	    const [currentPage, setCurrentPage] = useQueryState(
295	        FINANCIAL_PAGE_PARAM,
296	        parseAsInteger.withDefault(1),
297	    );
298	    const [isArchivedModalOpen, setIsArchivedModalOpen] = useState(false);
299	    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
300	    const [isImportHistoryModalOpen, setIsImportHistoryModalOpen] = useState(false);
301	    const [isCreateCessionarioModalOpen, setIsCreateCessionarioModalOpen] = useState(false);
302	    const [isListCessionariosModalOpen, setIsListCessionariosModalOpen] = useState(false);
303	    const [activeScenario, setActiveScenario] =
304	        useState<(typeof SCENARIO_TABS)[number]['id']>('base');
305	    const splitRef = useRef<HTMLDivElement>(null);
306	    const filterBarRef = useRef<HTMLDivElement>(null);
307	    const tabsRef = useRef<HTMLDivElement>(null);
308	    const listPanelRef = useRef<HTMLDivElement>(null);
309	    const detailPanelRef = useRef<HTMLDivElement>(null);
310	
311	    const notchPath = useNotchClipPath(splitRef);
312	
313	    /* ── Animação 1: filter bar — IntersectionObserver (sempre no DOM) ── */
314	    useEffect(() => {
315	        const el = filterBarRef.current;
316	        if (!el) return;
317	        let fired = false;
318	        const observer = new IntersectionObserver(
319	            (entries) => {
320	                if (entries[0].isIntersecting && !fired) {
321	                    fired = true;
322	                    observer.disconnect();
323	                    gsap.fromTo(
324	                        el,
325	                        { opacity: 0, y: -24, filter: 'blur(10px)' },
326	                        {
327	                            opacity: 1,
328	                            y: 0,
329	                            filter: 'blur(0px)',
330	                            duration: 0.7,
331	                            ease: 'power2.out',
332	                            clearProps: 'filter,transform',
333	                        },
334	                    );
335	                }
336	            },
337	            { threshold: 0.15 },
338	        );
339	        observer.observe(el);
340	        return () => observer.disconnect();
341	    }, []);
342	
343	    const userRole = useUserInfoStore((store) => store.data.role);
344	    const isMaster = userRole === 'MASTER';
345	    const hideCessionarioFilter = isInvestorCessionarioScopedRole(userRole);
346	
347	    useEffect(() => {
348	        if (hideCessionarioFilter && urlFilters.cessionario) {
349	            setUrlFilters({ cessionario: null });
350	        }
351	    }, [hideCessionarioFilter, urlFilters.cessionario, setUrlFilters]);
352	
353	    const isMobile = useIsMobile();
354	    const [api, setApi] = useState<CarouselApi>();
355	    const [current, setCurrent] = useState(0);
356	
357	    const filterSignature = useMemo(
358	        () =>
359	            [
360	                urlFilters.credor,
361	                urlFilters.cessionario,
362	                urlFilters.cedente,
363	                urlFilters.estado_ente_devedor,
364	                urlFilters.ente_devedor,
365	                urlFilters.loa,
366	                urlFilters.esfera,
367	                urlFilters.natureza,
368	                urlFilters.data_aquisicao,
369	                urlFilters.data_prev_pag,
370	                urlFilters.data_transmissao,
371	                urlFilters.valor_liquido,
372	                urlFilters.revisado,
373	                urlFilters.importado,
374	            ].join('|'),
375	        [urlFilters],
376	    );
377	
378	    const isFirstFilterSync = useRef(true);
379	    useEffect(() => {
380	        if (isFirstFilterSync.current) {
381	            isFirstFilterSync.current = false;
382	            return;
383	        }
384	        void setCurrentPage(1);
385	    }, [filterSignature, setCurrentPage]);
386	
387	    const valorLiquidoDisplayValue = useMemo(() => {
388	        if (!urlFilters.valor_liquido) return undefined;
389	        const opcao = VALOR_LIQUIDO_OPCOES.find((opt) => opt.value === urlFilters.valor_liquido);
390	        return opcao?.label;
391	    }, [urlFilters.valor_liquido]);
392	
393	    const revisadoDisplayValue = useMemo(() => {
394	        if (!urlFilters.revisado) return undefined;
395	        return REVISADO_OPTIONS.find((opt) => opt.value === urlFilters.revisado)?.label;
396	    }, [urlFilters.revisado]);
397	
398	    const importadoDisplayValue = useMemo(() => {
399	        if (!urlFilters.importado) return undefined;
400	        return IMPORTADO_OPTIONS.find((opt) => opt.value === urlFilters.importado)?.label;
401	    }, [urlFilters.importado]);
402	
403	    const { data: cessionariosData = [] } = useGetCessionariosQuery({
404	        enabled: !hideCessionarioFilter,
405	    });
406	
407	    const cessionariosOptions = useMemo(() => {
408	        const uniqueNames = Array.from(
409	            new Set(
410	                cessionariosData
411	                    .map((cessionario) => cessionario.nome?.trim())
412	                    .filter((name): name is string => Boolean(name)),
413	            ),
414	        ).sort((a, b) => a.localeCompare(b));
415	
416	        return uniqueNames.map((name) => ({ label: name, value: name }));
417	    }, [cessionariosData]);
418	
419	    async function handleCadastrarCessionario(pessoa: PessoaCadastrada) {
420	        try {
421	            const payload = buildCedentePayloadFromPessoa(pessoa);
422	            await criarCessionario(payload);
423	
424	            sendToastMessage({
425	                title: 'Cessionário cadastrado!',
426	                description: `${pessoa.nome} foi cadastrado com sucesso.`,
427	                type: 'success',
428	            });
429	
430	            queryClient.invalidateQueries({
431	                queryKey: [QueryKeys.cessionarios.list],
432	                exact: false,
433	            });
434	        } catch {
435	            sendToastMessage({
436	                title: 'Erro ao cadastrar cessionário',
437	                description: 'Não foi possível concluir o cadastro. Tente novamente.',
438	                type: 'error',
439	            });
440	        }
441	    }
442	
443	    const entesOptions = useMemo(() => {
444	        const entes = getOpcoesEntes(
445	            urlFilters.estado_ente_devedor || undefined,
446	            urlFilters.esfera ?? undefined,
447	        );
448	        return Array.from(new Set(entes))
449	            .sort((a, b) => a.localeCompare(b))
450	            .map((ente) => ({ label: ente, value: ente }));
451	    }, [urlFilters.esfera, urlFilters.estado_ente_devedor]);
452	
453	    const filters: FilterType[] = useMemo(
454	        () => [
455	            { id: 'credor', label: 'Credor', value: urlFilters.credor },
456	            ...(hideCessionarioFilter
457	                ? []
458	                : [{ id: 'cessionario', label: 'Cessionário', value: urlFilters.cessionario }]),
459	            { id: 'cedente', label: 'Cedente', value: urlFilters.cedente },
460	            {
461	                id: 'estado_ente_devedor',
462	                label: 'Estado do Ente Devedor',
463	                value: urlFilters.estado_ente_devedor,
464	            },
465	            { id: 'ente_devedor', label: 'Ente Devedor', value: urlFilters.ente_devedor },
466	            { id: 'loa', label: 'LOA', value: urlFilters.loa },
467	            { id: 'esfera', label: 'Esfera', value: urlFilters.esfera },
468	            { id: 'natureza', label: 'Natureza', value: urlFilters.natureza },
469	            { id: 'data_aquisicao', label: 'Data de Aquisição', value: urlFilters.data_aquisicao },
470	            {
471	                id: 'data_prev_pag',
472	                label: 'Previsão de Pagamento',
473	                value: urlFilters.data_prev_pag,
474	            },
475	            {
476	                id: 'data_transmissao',
477	                label: 'Data de Transmissão',
478	                value: urlFilters.data_transmissao,
479	            },
480	            {
481	                id: 'valor_liquido',
482	                label: 'Valor Líquido',
483	                value: urlFilters.valor_liquido,
484	                displayValue: valorLiquidoDisplayValue,
485	            },
486	            {
487	                id: 'revisado',
488	                label: 'Revisado',
489	                value:
490	                    urlFilters.revisado === 'true'
491	                        ? true
492	                        : urlFilters.revisado === 'false'
493	                            ? false
494	                            : undefined,
495	                displayValue: revisadoDisplayValue,
496	            },
497	            {
498	                id: 'importado',
499	                label: 'Importado',
500	                value:
501	                    urlFilters.importado === 'true'
502	                        ? true
503	                        : urlFilters.importado === 'false'
504	                            ? false
505	                            : undefined,
506	                displayValue: importadoDisplayValue,
507	            },
508	        ],
509	        [
510	            urlFilters.credor,
511	            hideCessionarioFilter,
512	            urlFilters.cessionario,
513	            urlFilters.cedente,
514	            urlFilters.estado_ente_devedor,
515	            urlFilters.ente_devedor,
516	            urlFilters.loa,
517	            urlFilters.esfera,
518	            urlFilters.natureza,
519	            urlFilters.data_aquisicao,
520	            urlFilters.data_prev_pag,
521	            urlFilters.data_transmissao,
522	            urlFilters.valor_liquido,
523	            valorLiquidoDisplayValue,
524	            urlFilters.revisado,
525	            revisadoDisplayValue,
526	            urlFilters.importado,
527	            importadoDisplayValue,
528	        ],
529	    );
530	
531	    const {
532	        data: postAquisitionData,
533	        error,
534	        isFetching,
535	        refetch,
536	        isLoading,
537	    } = useQuery(createPostAquisitionQuery(filters, currentPage));
538	
539	    /* ── Animação 2: split — aguarda isLoading, depois IntersectionObserver na viewport ── */
540	    useEffect(() => {
541	        if (isLoading) return;
542	
543	        // Elemento entra no DOM após isLoading=false; agora podemos observar a viewport.
544	        const anchor = splitRef.current;
545	        if (!anchor) return;
546	
547	        let fired = false;
548	        let timer: ReturnType<typeof setTimeout>;
549	        let ctx: gsap.Context | null = null;
550	
551	        const observer = new IntersectionObserver(
552	            (entries) => {
553	                if (entries[0].isIntersecting && !fired) {
554	                    fired = true;
555	                    observer.disconnect();
556	                    timer = setTimeout(() => {
557	                        const tabs = tabsRef.current;
558	                        const list = listPanelRef.current;
559	                        const detail = detailPanelRef.current;
560	                        ctx = gsap.context(() => {
561	                            const tl = gsap.timeline();
562	                            if (tabs) {
