    urlFilters: PostAquisitionCardsUrlFiltersGetter;
    setUrlFilters: PostAquisitionCardsUrlFiltersSetter;
    onDataChange?: (items: PosAquisicaoWithCedentes[]) => void;
    onEditItem?: (investmentId: string) => void;
