};

/* ─── Lista compacta item (painel esquerdo) — visual VisaoFinanceira ─── */
function AssetListItem({
    investment,
    isSelected,
    onClick,
    index,
}: {
    investment: PosAquisicaoWithCedentes;
    isSelected: boolean;
    onClick: () => void;
    index: number;
}) {
    const scenarioKey = mapScenarioFromAPI(investment.selected_scenario) || 'base';
    const scenario = investment.profitability_scenarios?.[scenarioKey];
    const tir = parseNullableDecimal(scenario?.tir);
    const moic = parseNullableDecimal(scenario?.moic);
    const valorLiquido = parseFloat(investment.valor_liquido_disponivel || '0');
    const cessionario = investment.cessionarios?.[0]?.nome || '-';
    const cessaoRegistrada = !!investment.cessao_registrada;

    return (
        <button
            onClick={onClick}
            className={cn(
                'relative flex flex-col gap-1.5 rounded-2xl border px-3.5 py-3 text-left transition-all duration-200',
                isSelected
                    ? 'border-[#96FF00]/30 bg-[#f3f6f9] shadow-[0_4px_16px_-4px_rgba(0,0,0,0.10),0_0_0_1px_rgba(150,255,0,0.10)] dark:border-[#96FF00]/10 dark:bg-[#131a21] dark:shadow-[0_8px_24px_-8px_rgba(0,0,0,0.6),0_0_0_1px_rgba(150,255,0,0.05)]'
                    : 'border-transparent hover:bg-black/3 dark:hover:bg-white/4',
            )}
        >
            {index > 0 && !isSelected && (
                <div className="absolute -top-px left-3.5 right-3.5 h-px bg-black/6 dark:bg-white/[0.07]" />
            )}

            <div className="flex items-center justify-between gap-2">
                <p
                    className={cn(
                        'truncate text-sm font-bold tracking-tight',
                        isSelected
                            ? 'text-[#0b1014] dark:text-white'
                            : 'text-[#536471] dark:text-[#8a9097]',
                    )}
                >
                    {investment.credor}
                </p>
                <div className="flex shrink-0 items-center gap-1">
                    <ImportadoBadge
                        importado={!!investment.importado}
                        variant="icon"
                    />
                    <span
                        className={cn(
                            badgeVariants({ variant: investment.revisado ? 'green' : 'red' }),
                            'shrink-0 border-none px-1.5 py-px text-[8px] font-bold uppercase tracking-wide',
                        )}
                    >
                        {investment.revisado ? 'Revisado' : 'Não revisado'}
                    </span>
                </div>
            </div>

            <div
                className={cn(
                    'flex items-center gap-1.5 text-[11px] font-medium',
                    isSelected
                        ? 'text-[#536471] dark:text-[#6f7a83]'
                        : 'text-[#5d6770] dark:text-[#8a9097]',
                )}
            >
                <span
                    className={cn(
                        'h-[5px] w-[5px] shrink-0 rounded-full',
                        cessaoRegistrada ? 'bg-[#96FF00]' : 'bg-[#f97316]',
                    )}
                />
                <span className="truncate">
                    {cessionario} · {investment.ente_devedor}
                </span>
            </div>

            <div className="flex items-center gap-3 text-[11px] tabular-nums">
                {/* Qualifica justamente a TIR e o MOIC ao lado, que podem ser do
                    snapshot anterior quando o recálculo falhou. */}
                <MarcadorCenarioCalc recurso={investment} />
                {(
                    [
                        [
                            'TIR',
                            tir !== null ? `${(tir * 100).toFixed(1)}%` : '—',
                            isSelected
                                ? 'text-[#4d8f00] dark:text-[#96FF00]'
                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
                        ],
                        [
                            'MOIC',
                            moic !== null ? `${moic.toFixed(2)}x` : '—',
                            isSelected
                                ? 'text-[#536471] dark:text-white'
                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
                        ],
                        [
                            'Vlr.',
                            `R$ ${(valorLiquido / 1000).toFixed(1)}k`,
                            isSelected
                                ? 'text-[#536471] dark:text-white'
                                : 'text-[#9aa5ad] dark:text-[#5d6770]',
                        ],
                    ] as const
                ).map(([label, value, color]) => (
                    <span key={label}>
                        <span className="text-[#8a9097] dark:text-[#3d4850]">{label} </span>
                        <span className={cn('font-semibold', color)}>{value}</span>
                    </span>
                ))}
            </div>
        </button>
    );
}

