/* ─── Main wrapper ─── */
export function IndividualCardsWrapper({
    urlFilters,
    setUrlFilters,
    onDataChange,
    onEditItem,
    onNewItem,
}: IndividualCardsWrapperProps) {
    const [individualViewMode, setIndividualViewMode] = useQueryState(
        'individual_view_mode',
        parseAsString.withDefault(getStorageItem('individual_view_mode') ?? 'rows'),
    );
    const [selectedId, setSelectedId] = useQueryState(FINANCIAL_ATIVO_PARAM, parseAsString);
    const [currentPage, setCurrentPage] = useQueryState(
        FINANCIAL_PAGE_PARAM,
        parseAsInteger.withDefault(1),
    );
    const [isArchivedModalOpen, setIsArchivedModalOpen] = useState(false);
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
    const [isImportHistoryModalOpen, setIsImportHistoryModalOpen] = useState(false);
    const [isCreateCessionarioModalOpen, setIsCreateCessionarioModalOpen] = useState(false);
    const [isListCessionariosModalOpen, setIsListCessionariosModalOpen] = useState(false);
    const [activeScenario, setActiveScenario] =
        useState<(typeof SCENARIO_TABS)[number]['id']>('base');
    const splitRef = useRef<HTMLDivElement>(null);
    const filterBarRef = useRef<HTMLDivElement>(null);
    const tabsRef = useRef<HTMLDivElement>(null);
    const listPanelRef = useRef<HTMLDivElement>(null);
    const detailPanelRef = useRef<HTMLDivElement>(null);

    const notchPath = useNotchClipPath(splitRef);

    /* ── Animação 1: filter bar — IntersectionObserver (sempre no DOM) ── */
    useEffect(() => {
        const el = filterBarRef.current;
        if (!el) return;
        let fired = false;
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !fired) {
                    fired = true;
                    observer.disconnect();
                    gsap.fromTo(
                        el,
                        { opacity: 0, y: -24, filter: 'blur(10px)' },
                        {
                            opacity: 1,
                            y: 0,
                            filter: 'blur(0px)',
                            duration: 0.7,
                            ease: 'power2.out',
                            clearProps: 'filter,transform',
                        },
                    );
                }
            },
            { threshold: 0.15 },
        );
        observer.observe(el);
        return () => observer.disconnect();
    }, []);

    const userRole = useUserInfoStore((store) => store.data.role);
    const isMaster = userRole === 'MASTER';
    const hideCessionarioFilter = isInvestorCessionarioScopedRole(userRole);

    useEffect(() => {
        if (hideCessionarioFilter && urlFilters.cessionario) {
            setUrlFilters({ cessionario: null });
        }
    }, [hideCessionarioFilter, urlFilters.cessionario, setUrlFilters]);

    const isMobile = useIsMobile();
    const [api, setApi] = useState<CarouselApi>();
    const [current, setCurrent] = useState(0);

    const filterSignature = useMemo(
        () =>
            [
                urlFilters.credor,
                urlFilters.cessionario,
                urlFilters.cedente,
                urlFilters.estado_ente_devedor,
                urlFilters.ente_devedor,
                urlFilters.loa,
                urlFilters.esfera,
                urlFilters.natureza,
                urlFilters.data_aquisicao,
                urlFilters.data_prev_pag,
                urlFilters.data_transmissao,
                urlFilters.valor_liquido,
                urlFilters.revisado,
                urlFilters.importado,
            ].join('|'),
        [urlFilters],
    );

    const isFirstFilterSync = useRef(true);
    useEffect(() => {
        if (isFirstFilterSync.current) {
            isFirstFilterSync.current = false;
            return;
        }
        void setCurrentPage(1);
    }, [filterSignature, setCurrentPage]);

    const valorLiquidoDisplayValue = useMemo(() => {
        if (!urlFilters.valor_liquido) return undefined;
        const opcao = VALOR_LIQUIDO_OPCOES.find((opt) => opt.value === urlFilters.valor_liquido);
        return opcao?.label;
    }, [urlFilters.valor_liquido]);

    const revisadoDisplayValue = useMemo(() => {
        if (!urlFilters.revisado) return undefined;
        return REVISADO_OPTIONS.find((opt) => opt.value === urlFilters.revisado)?.label;
    }, [urlFilters.revisado]);

    const importadoDisplayValue = useMemo(() => {
        if (!urlFilters.importado) return undefined;
        return IMPORTADO_OPTIONS.find((opt) => opt.value === urlFilters.importado)?.label;
    }, [urlFilters.importado]);

    const { data: cessionariosData = [] } = useGetCessionariosQuery({
        enabled: !hideCessionarioFilter,
    });

    const cessionariosOptions = useMemo(() => {
        const uniqueNames = Array.from(
            new Set(
                cessionariosData
                    .map((cessionario) => cessionario.nome?.trim())
                    .filter((name): name is string => Boolean(name)),
            ),
        ).sort((a, b) => a.localeCompare(b));

        return uniqueNames.map((name) => ({ label: name, value: name }));
    }, [cessionariosData]);

    async function handleCadastrarCessionario(pessoa: PessoaCadastrada) {
        try {
            const payload = buildCedentePayloadFromPessoa(pessoa);
            await criarCessionario(payload);

            sendToastMessage({
                title: 'Cessionário cadastrado!',
                description: `${pessoa.nome} foi cadastrado com sucesso.`,
                type: 'success',
            });

            queryClient.invalidateQueries({
                queryKey: [QueryKeys.cessionarios.list],
                exact: false,
            });
        } catch {
            sendToastMessage({
                title: 'Erro ao cadastrar cessionário',
                description: 'Não foi possível concluir o cadastro. Tente novamente.',
                type: 'error',
            });
        }
    }

    const entesOptions = useMemo(() => {
        const entes = getOpcoesEntes(
            urlFilters.estado_ente_devedor || undefined,
            urlFilters.esfera ?? undefined,
        );
        return Array.from(new Set(entes))
            .sort((a, b) => a.localeCompare(b))
            .map((ente) => ({ label: ente, value: ente }));
    }, [urlFilters.esfera, urlFilters.estado_ente_devedor]);

    const filters: FilterType[] = useMemo(
        () => [
            { id: 'credor', label: 'Credor', value: urlFilters.credor },
            ...(hideCessionarioFilter
                ? []
                : [{ id: 'cessionario', label: 'Cessionário', value: urlFilters.cessionario }]),
            { id: 'cedente', label: 'Cedente', value: urlFilters.cedente },
            {
                id: 'estado_ente_devedor',
                label: 'Estado do Ente Devedor',
                value: urlFilters.estado_ente_devedor,
            },
            { id: 'ente_devedor', label: 'Ente Devedor', value: urlFilters.ente_devedor },
            { id: 'loa', label: 'LOA', value: urlFilters.loa },
            { id: 'esfera', label: 'Esfera', value: urlFilters.esfera },
            { id: 'natureza', label: 'Natureza', value: urlFilters.natureza },
            { id: 'data_aquisicao', label: 'Data de Aquisição', value: urlFilters.data_aquisicao },
            {
                id: 'data_prev_pag',
                label: 'Previsão de Pagamento',
                value: urlFilters.data_prev_pag,
            },
            {
                id: 'data_transmissao',
                label: 'Data de Transmissão',
                value: urlFilters.data_transmissao,
            },
            {
                id: 'valor_liquido',
                label: 'Valor Líquido',
                value: urlFilters.valor_liquido,
                displayValue: valorLiquidoDisplayValue,
            },
            {
                id: 'revisado',
                label: 'Revisado',
                value:
                    urlFilters.revisado === 'true'
                        ? true
                        : urlFilters.revisado === 'false'
                            ? false
                            : undefined,
                displayValue: revisadoDisplayValue,
            },
            {
                id: 'importado',
                label: 'Importado',
                value:
                    urlFilters.importado === 'true'
                        ? true
                        : urlFilters.importado === 'false'
                            ? false
                            : undefined,
                displayValue: importadoDisplayValue,
            },
        ],
        [
            urlFilters.credor,
            hideCessionarioFilter,
            urlFilters.cessionario,
            urlFilters.cedente,
            urlFilters.estado_ente_devedor,
            urlFilters.ente_devedor,
            urlFilters.loa,
            urlFilters.esfera,
            urlFilters.natureza,
            urlFilters.data_aquisicao,
            urlFilters.data_prev_pag,
            urlFilters.data_transmissao,
            urlFilters.valor_liquido,
            valorLiquidoDisplayValue,
            urlFilters.revisado,
            revisadoDisplayValue,
            urlFilters.importado,
            importadoDisplayValue,
        ],
    );

    const {
        data: postAquisitionData,
        error,
        isFetching,
        refetch,
        isLoading,
    } = useQuery(createPostAquisitionQuery(filters, currentPage));

    /* ── Animação 2: split — aguarda isLoading, depois IntersectionObserver na viewport ── */
    useEffect(() => {
        if (isLoading) return;

        // Elemento entra no DOM após isLoading=false; agora podemos observar a viewport.
        const anchor = splitRef.current;
        if (!anchor) return;

        let fired = false;
        let timer: ReturnType<typeof setTimeout>;
        let ctx: gsap.Context | null = null;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !fired) {
                    fired = true;
                    observer.disconnect();
                    timer = setTimeout(() => {
                        const tabs = tabsRef.current;
                        const list = listPanelRef.current;
                        const detail = detailPanelRef.current;
                        ctx = gsap.context(() => {
                            const tl = gsap.timeline();
                            if (tabs) {
                                tl.fromTo(
                                    tabs,
                                    { opacity: 0, y: -28, scale: 0.9 },
                                    {
                                        opacity: 1,
                                        y: 0,
                                        scale: 1,
                                        duration: 0.55,
                                        ease: 'back.out(1.5)',
                                        clearProps: 'transform',
                                    },
                                    0,
                                );
                            }
                            if (list) {
                                tl.fromTo(
                                    list,
                                    { opacity: 0, x: -60, filter: 'blur(14px)' },
                                    {
                                        opacity: 1,
                                        x: 0,
                                        filter: 'blur(0px)',
                                        duration: 0.9,
                                        ease: 'power2.out',
                                        clearProps: 'filter,transform',
                                    },
                                    0.1,
                                );
                            }
                            if (detail) {
                                tl.fromTo(
                                    detail,
                                    { opacity: 0, x: 60, filter: 'blur(14px)' },
                                    {
                                        opacity: 1,
                                        x: 0,
                                        filter: 'blur(0px)',
                                        duration: 0.9,
                                        ease: 'power2.out',
                                        clearProps: 'filter,transform',
                                    },
                                    0.2,
                                );
                            }
                        });
                    }, 30);
                }
            },
            { threshold: 0.05 },
        );
        observer.observe(anchor);

        return () => {
            observer.disconnect();
            clearTimeout(timer);
            ctx?.revert();
        };
    }, [isLoading]);

    const { data: extratosLoasData } = useQuery(getExtratosLoasQuery());

    const loasOptions = useMemo(
        () =>
            (extratosLoasData?.loas ?? []).map((loa) => ({
                label: String(loa),
                value: String(loa),
            })),
        [extratosLoasData],
    );

    const filterOptions = useMemo(
        () => ({
            cessionarios: cessionariosOptions,
            entes: entesOptions,
            loas: loasOptions,
        }),
        [cessionariosOptions, entesOptions, loasOptions],
    );

    /* Seleciona primeiro item quando dados chegam ou página muda */
    useEffect(() => {
        if (!postAquisitionData?.results?.length) return;

        const stillExists = selectedId
            ? postAquisitionData.results.some((r) => r.id === selectedId)
            : false;

        if (!stillExists) {
            void setSelectedId(postAquisitionData.results[0].id);
        }
    }, [postAquisitionData, selectedId, setSelectedId]);

    /* Notifica o pai com os itens da página atual */
    useEffect(() => {
        onDataChange?.(postAquisitionData?.results ?? []);
    }, [postAquisitionData, onDataChange]);

    function handleChangePage(direction: 'next' | 'previous') {
        void setCurrentPage(currentPage + (direction === 'next' ? 1 : -1));
        void setSelectedId(null);
    }

    useEffect(() => {
        if (!api) return;
        const onSelect = () => setCurrent(api.selectedScrollSnap());
        const onInit = () => {
            setCurrent(api.selectedScrollSnap());
            api.scrollTo(0, true);
        };
        onInit();
        api.on('select', onSelect);
        api.on('reInit', onInit);
        return () => {
            api.off('select', onSelect);
            api.off('reInit', onInit);
        };
    }, [api]);

    useEffect(() => {
        setStorageItem('individualViewMode', individualViewMode);
    }, [individualViewMode]);

    useEffect(() => {
        if (postAquisitionData?.next) {
            const nextPage = currentPage + 1;
            queryClient.prefetchQuery({
                queryKey: [QueryKeys.postAquisition.precatorios, filters, nextPage],
                queryFn: () => getPostPurchases(filters, nextPage),
            });
        }
    }, [postAquisitionData, currentPage, filters]);

    const selectedInvestment = useMemo(
        () => postAquisitionData?.results?.find((r) => r.id === selectedId) ?? null,
        [postAquisitionData, selectedId],
    );

    // Sincroniza as tabs de cenário com o cenário salvo do investimento selecionado
    useEffect(() => {
        if (selectedInvestment) {
            const mapped = mapScenarioFromAPI(selectedInvestment.selected_scenario);
            if (mapped) setActiveScenario(mapped as (typeof SCENARIO_TABS)[number]['id']);
        }
    }, [selectedInvestment]);

    if (error) {
        return (
            <ErrorMessageBox
                className="flex w-full items-center justify-center"
                retryFn={refetch}
                isRetrying={isFetching}
            />
        );
    }

    return (
        <div className="flex w-full min-w-0 max-w-full flex-col gap-4 px-3 pb-6 sm:px-4 md:px-6 lg:px-8">
            <div ref={filterBarRef} className="min-w-0">
                <IndividualCardsHeader
                    isLoading={isLoading}
                    filters={filters}
                    individualViewMode={individualViewMode}
                    setIndividualViewMode={setIndividualViewMode}
                    urlFilters={urlFilters}
                    setUrlFilters={setUrlFilters}
                    filterOptions={filterOptions}
                    hideCessionarioFilter={hideCessionarioFilter}
                    onArchivedClick={() => setIsArchivedModalOpen(true)}
                    onNewItem={onNewItem}
                    paginationControls={
                        <div className="flex items-center gap-1.5">
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleChangePage('previous')}
                                disabled={!postAquisitionData?.previous}
                                className="h-8 px-2 text-xs"
                                aria-label="Página anterior"
                            >
                                ←
                            </Button>
                            <span className="text-xs tabular-nums text-gray-400">
                                {currentPage}
                            </span>
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleChangePage('next')}
                                disabled={!postAquisitionData?.next}
                                className="h-8 px-2 text-xs"
                                aria-label="Próxima página"
                            >
                                →
                            </Button>
                        </div>
                    }
                />
            </div>

            {isLoading ? (
                <IndividualCardSkeleton />
            ) : isMobile ? (
                /* ── Mobile: carousel ── */
                <div className="space-y-4">
                    <Carousel opts={{ align: 'start' }} setApi={setApi}>
                        <CarouselContent className="pb-2">
                            {postAquisitionData?.results.map((investment) => (
                                <CarouselItem
                                    key={investment.id}
                                    className="basis-[92%] pl-3 sm:basis-[85%] sm:pl-4"
                                >
                                    <IndividualCardDetail
                                        investment={investment}
                                        onEditItem={onEditItem}
                                    />
                                </CarouselItem>
                            ))}
                        </CarouselContent>
                        <div className="flex flex-wrap justify-center gap-1.5 py-2">
                            {postAquisitionData?.results.map((_, i) => (
                                <button
                                    key={i}
                                    type="button"
                                    aria-label={`Ir para card ${i + 1}`}
                                    aria-current={i === current ? 'true' : undefined}
                                    className="flex h-9 w-9 cursor-pointer items-center justify-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#96FF00]/40"
                                    onClick={() => {
                                        api?.scrollTo(i);
                                        setCurrent(i);
                                    }}
                                >
                                    <span
                                        className={cn(
                                            'block rounded-full transition-all',
                                            i === current ? 'h-2 w-4 bg-meta-3' : 'h-2 w-2 bg-muted',
                                        )}
                                    />
                                </button>
                            ))}
                        </div>
                        <p className="text-center text-sm text-muted-foreground">
                            Mostrando {current + 1} - {postAquisitionData?.results.length ?? 0}
                        </p>
                    </Carousel>
                </div>
            ) : (
                /* ── Desktop/notebook: split responsivo com notch ── */
                <div className="relative mt-4 flex min-h-0 w-full min-w-0 flex-col sm:mt-6">
                    {/* Tabs de cenário flutuando no notch */}
                    <div className="pointer-events-none absolute inset-x-0 top-0 z-20 flex h-12 items-center justify-center px-2 sm:h-[54px]">
                        <div
                            ref={tabsRef}
                            className="pointer-events-auto inline-flex max-w-full flex-wrap items-center justify-center gap-1.5 sm:gap-2"
                        >
                            {SCENARIO_TABS.map((tab) => {
                                const active = activeScenario === tab.id;
                                const color = SCENARIO_TAB_COLORS[tab.id];
                                return (
                                    <button
                                        key={tab.id}
                                        type="button"
                                        onClick={() => setActiveScenario(tab.id)}
                                        style={
                                            active
                                                ? {
                                                    backgroundColor: color,
                                                    boxShadow: `0 0 24px ${color}4D`,
                                                }
                                                : undefined
                                        }
                                        className={cn(
                                            'flex h-8 cursor-pointer items-center rounded-full px-3 text-[12px] font-semibold tracking-wide transition-all duration-200 sm:h-[38px] sm:px-5 sm:text-[13px] xl:px-7 xl:text-[14px]',
                                            active
                                                ? 'text-white'
                                                : 'border-2 border-stroke bg-white text-[#536471] shadow-sm hover:bg-[#f5f7fa] hover:text-[#0b1014] dark:border-[#1a2228] dark:bg-[#131920] dark:text-[#6f7a83] dark:shadow-none dark:hover:bg-[#182028] dark:hover:text-[#9aa5ad]',
                                        )}
                                    >
                                        {tab.label}
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/*
                      Estrutura original: split lista | detalhe.
                      Coluna flexível evita overflow em notebook; 390px no xl+.
                    */}
                    <div
                        ref={splitRef}
                        className={cn(
                            'grid h-[min(600px,70vh)] min-w-0 gap-3.5 rounded-[24px] bg-white px-2 pb-7 pt-[66px] dark:bg-[#0a0e11]',
                            'grid-cols-[minmax(220px,min(34%,320px))_minmax(0,1fr)]',
                            'xl:grid-cols-[390px_minmax(0,1fr)]',
                        )}
                    >
                        {/* Lista (painel esquerdo) */}
                        <div
                            ref={listPanelRef}
                            className="flex min-h-0 min-w-0 flex-col rounded-[18px] px-2 pb-2 sm:px-3"
                        >
                            <div className="mt-[-50px] mb-4 flex min-w-0 items-center gap-2 sm:mb-6">
                                <h3 className="min-w-0 truncate text-lg font-bold tracking-tight text-[#0b1014] dark:text-white sm:text-xl">
                                    Ativos Individualizados
                                </h3>
                                {isFetching && !isLoading && (
                                    <LoaderCircle className="h-4 w-4 shrink-0 animate-spin text-[#96FF00]" />
                                )}
                            </div>

                            <div className="flex min-h-0 flex-1 flex-col gap-0.5 overflow-auto pr-1 sm:pr-2 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-[#b2b2b2] dark:[&::-webkit-scrollbar-thumb]:bg-[#2f485c] [&::-webkit-scrollbar-track]:rounded-full [&::-webkit-scrollbar-track]:bg-[#f4f6f8] dark:[&::-webkit-scrollbar-track]:bg-[#1f2c36] [&::-webkit-scrollbar]:w-1">
                                {postAquisitionData?.results.length === 0 ? (
                                    <div className="flex min-h-40 items-center justify-center p-4">
                                        <p className="text-center text-sm text-[#8a9097] dark:text-[#6f7a83]">
                                            Nenhum ativo encontrado.
                                        </p>
                                    </div>
                                ) : (
                                    postAquisitionData?.results.map((investment, idx) => (
                                        <AssetListItem
                                            key={investment.id}
                                            index={idx}
                                            investment={investment}
                                            isSelected={selectedId === investment.id}
                                            onClick={() => void setSelectedId(investment.id)}
                                        />
                                    ))
                                )}
                            </div>

                            {/* Rodapé: legenda + paginação */}
                            <div className="mt-2 border-t border-black/6 pt-3 dark:border-white/[0.07]">
                                <div className="mb-2.5 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-[#8a9097] dark:text-[#6f7a83]">
                                    <span className="flex items-center gap-1.5">
                                        <span className="h-[5px] w-[5px] rounded-full bg-[#96FF00]" />
                                        Cessão registrada
                                    </span>
                                    <span className="flex items-center gap-1.5">
                                        <span className="h-[5px] w-[5px] rounded-full bg-[#f97316]" />
                                        Não registrada
                                    </span>
                                </div>
                                <div className="flex items-center justify-between gap-2">
                                    <span className="min-w-0 truncate text-[11px] text-[#8a9097] dark:text-[#6f7a83]">
                                        {postAquisitionData &&
                                            paginatedTableDisplayMessage(
                                                currentPage,
                                                postAquisitionData,
                                            )}
                                    </span>
                                    <div className="flex shrink-0 items-center gap-1.5">
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            onClick={() => handleChangePage('previous')}
                                            disabled={!postAquisitionData?.previous}
                                            className="h-6 px-2 text-xs"
                                            aria-label="Página anterior"
                                        >
                                            ←
                                        </Button>
                                        <span className="text-[11px] tabular-nums text-[#8a9097] dark:text-[#6f7a83]">
                                            {currentPage}
                                        </span>
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            onClick={() => handleChangePage('next')}
                                            disabled={!postAquisitionData?.next}
                                            className="h-6 px-2 text-xs"
                                            aria-label="Próxima página"
                                        >
                                            →
                                        </Button>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Detalhe (painel direito) */}
                        <div ref={detailPanelRef} className="relative min-h-0 min-w-0">
                            {selectedInvestment ? (
                                <IndividualCardDetail
                                    key={selectedInvestment.id}
                                    investment={selectedInvestment}
                                    onEditItem={onEditItem}
                                    externalScenario={activeScenario as ScenarioKey}
                                    onArchivedClick={() => setIsArchivedModalOpen(true)}
                                    onNewItem={onNewItem}
                                    onExportClick={() => setIsExportModalOpen(true)}
                                    onImportHistoryClick={() => setIsImportHistoryModalOpen(true)}
                                    onCreateCessionarioClick={() =>
                                        setIsCreateCessionarioModalOpen(true)
                                    }
                                    onListCessionariosClick={() =>
                                        setIsListCessionariosModalOpen(true)
                                    }
                                />
                            ) : (
                                <EmptyDetail />
                            )}
                        </div>
                    </div>

                    {/* Borda do container seguindo o notch — verde no dark */}
                    {notchPath && (
                        <svg
                            className="pointer-events-none absolute inset-x-0 top-0 z-15 h-full"
                            viewBox={`0 0 ${notchPath.w} ${notchPath.h}`}
                            preserveAspectRatio="none"
                            fill="none"
                        >
                            <path
                                d={notchPath.d}
                                strokeWidth="1.5"
                                vectorEffect="non-scaling-stroke"
                                className="stroke-[#e2e8f0] dark:stroke-[rgba(150,255,0,0.30)]"
                            />
                        </svg>
                    )}
                </div>
            )}

            {isMaster && (
                <ArchivedPostPurchaseListModal
                    open={isArchivedModalOpen}
                    onOpenChange={setIsArchivedModalOpen}
                />
            )}
            {isMaster && (
                <ExportPosAquisicaoModal
                    open={isExportModalOpen}
                    onOpenChange={setIsExportModalOpen}
                    initialCessionario={urlFilters.cessionario}
                />
            )}
            {isMaster && (
                <ImportacoesHistoryModal
                    open={isImportHistoryModalOpen}
                    onOpenChange={setIsImportHistoryModalOpen}
                />
            )}
            <CadastroCessionarioModal
                open={isCreateCessionarioModalOpen}
                onOpenChange={setIsCreateCessionarioModalOpen}
                onCadastrar={handleCadastrarCessionario}
            />
            <CessionariosListModal
                open={isListCessionariosModalOpen}
                onOpenChange={setIsListCessionariosModalOpen}
            />
        </div>
    );
}

